import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectFieldError,
  expectRecordTitle,
  expectToast,
  relatedListRecord,
  selectPicklist,
  showRelatedList,
  waitForSpinners,
} from '../../support/lightning.js';
import { soqlCount, soqlValue } from '../../support/api.js';

test.describe('SF-219 Boundary value test for Phone field: 9, 10, and 11 digit entries', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-010 Boundary value test for Phone field: 9, 10, and 11 digit entries',
    { tag: ['@functional', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-010',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const boundary9 = data.unique('boundary9');
      const boundary11 = data.unique('boundary11');
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Navigate to Account and open New Contact dialog', async () => {
        // Expected (DECLARED_CONFIG; SF-219#AC5, ValidationRule:Contact.Phone_Must_Be_10_Digits): Contact creation modal or page opens
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step('2. Enter 9-digit phone and attempt save - validation error expected', async () => {
        // Expected (DECLARED_CONFIG; ValidationRule:Contact.Phone_Must_Be_10_Digits, SF-219#AC5, OC-007): Contact is not saved and validation error 'Phone must be exactly 10 digits.' is displayed on the Phone field
        await newContactDialog.lastName.fill(boundary9);
        await selectPicklist(page, newContactDialog.leadSource, 'Word of mouth');
        await newContactDialog.phone.fill('555123456');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectFieldError(newContactDialog.phone, 'Phone must be exactly 10 digits.'); // message of rule Contact.Phone_Must_Be_10_Digits (org snapshot)
        expect(await soqlCount(sf, 'Contact', 'LastName', boundary9)).toBe(0);
      });
      await test.step('3. Enter 10-digit phone and save - contact record created', async () => {
        // Expected (DECLARED_CONFIG; ValidationRule:Contact.Phone_Must_Be_10_Digits, SF-219#AC5, OC-007): Contact record is saved and the Contact detail page opens showing Phone '5551234567'
        await newContactDialog.phone.fill('5551234567');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectToast(page, boundary9); // 1. the success toast names the record
        await expect(relatedListRecord(accountRecordPage.contactsRelatedList, boundary9)).toBeVisible(); // 2. in the related list with that name
        await data.adopt('Boundary10', 'Contact', 'LastName', boundary9); // code-owned cleanup: tagged by its run-unique name
        await relatedListRecord(accountRecordPage.contactsRelatedList, boundary9).click(); // 3. opened from the related list
        await expectRecordTitle(page, boundary9);
        {
          // 4. SOQL by the run tag: exactly this record, with the values entered
          const saved = await data.tagged('Contact', { LastName: boundary9 }, [
            'LastName',
            'LeadSource',
            'Phone',
            'Account.Name',
          ]);
          expect(saved).toHaveLength(1);
          expect(saved[0]).toMatchObject({
            LastName: boundary9,
            LeadSource: 'Word of mouth',
            Phone: '5551234567',
            'Account.Name': data.value('Account', 'Name'),
          });
        }
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('Boundary10'), 'Phone')).toBe('5551234567');
      });
      await test.step('4. Navigate to Account and open New Contact dialog again', async () => {
        // Expected (DECLARED_CONFIG; SF-219#AC5, ValidationRule:Contact.Phone_Must_Be_10_Digits): Contact creation modal or page opens
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step('5. Enter 11-digit phone and attempt save - validation error expected', async () => {
        // Expected (DECLARED_CONFIG; ValidationRule:Contact.Phone_Must_Be_10_Digits, SF-219#AC5, OC-007): Contact is not saved and validation error 'Phone must be exactly 10 digits.' is displayed on the Phone field
        await newContactDialog.lastName.fill(boundary11);
        await selectPicklist(page, newContactDialog.leadSource, 'Word of mouth');
        await newContactDialog.phone.fill('55512345678');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectFieldError(newContactDialog.phone, 'Phone must be exactly 10 digits.'); // message of rule Contact.Phone_Must_Be_10_Digits (org snapshot)
        expect(await soqlCount(sf, 'Contact', 'LastName', boundary11)).toBe(0);
      });
    },
  );
});
